package edu.carroll.cs341.web.controller;

import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.GetMapping;

/**
 * Handles requests to the application's root URL.
 * This controller directs users who access the root path to the
 * application's index page.
 *
 * <p><b>Sources Used:</b></p>
 * <ul>
 *   <li>ChatGPT – Assisted with generating Javadoc comments for this file
 *   in conjunction with Max Montowski.
 *   All comments were reviewed by the author. No code was generated by ChatGPT.</li>
 * </ul>
 */
@Controller
public class IndexController {

    /**
     * Displays the application's index page when the root URL is accessed.
     *
     * @return the name of the Thymeleaf view for the index page
     */
    @GetMapping("/")
    public String index() {
        // Return the view name that Spring uses to resolve the index page.
        return "index";
    }
}